// Package crypto wraps filippo.io/age: one X25519 keypair generated by init,
// the private key stays on the backup machine, the public key goes in app.yaml. → ADR-0008
package crypto

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"filippo.io/age"
)

// Keypair is a freshly generated age keypair.
type Keypair struct {
	Recipient string // age1…, written to app.yaml
	Identity  string // AGE-SECRET-KEY-1…, written to a mode 600 file
}

// Generate creates an X25519 keypair.
func Generate() (Keypair, error) {
	id, err := age.GenerateX25519Identity()
	if err != nil {
		return Keypair{}, err
	}
	return Keypair{Recipient: id.Recipient().String(), Identity: id.String()}, nil
}

// ParseRecipient validates a public key pasted in by the customer.
func ParseRecipient(s string) (string, error) {
	r, err := age.ParseX25519Recipient(strings.TrimSpace(s))
	if err != nil {
		return "", fmt.Errorf("invalid age public key: %w", err)
	}
	return r.String(), nil
}

// ErrExists: the key file already exists; it is never overwritten.
var ErrExists = fmt.Errorf("key file already exists")

// WriteIdentityFile writes the identity file in age-keygen format, mode 600,
// directory 700. It never overwrites.
func WriteIdentityFile(path string, kp Keypair) error {
	if _, err := os.Stat(path); err == nil {
		return fmt.Errorf("%s: %w", path, ErrExists)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	_, werr := fmt.Fprintf(f, "# created: %s\n# public key: %s\n%s\n", time.Now().UTC().Format(time.RFC3339), kp.Recipient, kp.Identity)
	cerr := f.Close()
	if werr != nil {
		return werr
	}
	return cerr
}

// AppendIdentity appends a new key to the end of the file (rotate-key keeps the old key).
func AppendIdentity(path string, kp Keypair) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0o600)
	if err != nil {
		return err
	}
	_, werr := fmt.Fprintf(f, "\n# rotated: %s\n# public key: %s\n%s\n", time.Now().UTC().Format(time.RFC3339), kp.Recipient, kp.Identity)
	cerr := f.Close()
	if werr != nil {
		return werr
	}
	return cerr
}

// ReadIdentities reads every key in the file and returns the matching recipients
// to compare against app.yaml.
func ReadIdentities(path string) ([]age.Identity, []string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, nil, err
	}
	defer f.Close()
	var ids []age.Identity
	var recips []string
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		id, err := age.ParseX25519Identity(line)
		if err != nil {
			return nil, nil, fmt.Errorf("%s: %w", path, err)
		}
		ids = append(ids, id)
		recips = append(recips, id.Recipient().String())
	}
	return ids, recips, sc.Err()
}

// Encrypt wraps w: everything written to the returned WriteCloser is encrypted for recipient.
func Encrypt(w io.Writer, recipient string) (io.WriteCloser, error) {
	r, err := age.ParseX25519Recipient(recipient)
	if err != nil {
		return nil, err
	}
	return age.Encrypt(w, r)
}

// Decrypt opens an encrypted stream using any of the keys in ids.
func Decrypt(r io.Reader, ids []age.Identity) (io.Reader, error) {
	return age.Decrypt(r, ids...)
}
